package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's people, in the order they were added. */
public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId, PersonRepository repository, SheetRepository sheets,
            ObjectResponse<PeopleResponse> response) {
        String sheet = sheetId.trim();
        LocalDate today = sheets.findById(sheet).map((s) -> s.getToday()).orElseGet(LocalDate::now);
        response.send(PeopleResponse.from(repository.findBySheetIdOrderByIdAsc(sheet), today));
    }
}
=== PeopleResponse
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A sheet's people, in the order they were added, each with the grade in force on the sheet's today. */
public record PeopleResponse(List<PersonResponse> people) {

    public static PeopleResponse from(List<Person> people, LocalDate today) {
        return new PeopleResponse(people.stream().map((p) -> PersonResponse.from(p, today)).toList());
    }
}
# Put a person on hold, or release them (the body says which). Validate before Load so a bad body is a
# 400, not masked by a 404; a person already in that state is refused (400) and writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
# Record the change only once it is saved, so a refused change writes no audit line.
audit:
  class: net.officefloor.hq.app.person.AuditPersonHold
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
-- A person may be put on hold, and released again. While held, their OPEN claims count in no live total
-- (their claimed and due-total, the sheet's totals, a period's due-total); their SETTLED claims still do.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- People on a sheet: each has a name and a grade (A, B or C). Listed in the order they were added
-- (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL,
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
import { useState } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { holdPerson, peopleKey, usePeople } from './people';

function HoldColumns() {
  return (
    <>
      <th>On hold</th>
      <th>Hold</th>
    </>
  );
}

// Whether a person is on hold, and a button that puts them on hold or releases them. A refusal shows
// on the row.
function PersonHold({ personId }: { personId: number }) {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const person = (usePeople().data ?? []).find((p) => p.id === personId);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const hold = useMutation({
    mutationFn: (held: boolean) => holdPerson(sheet!, user, personId, held),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) }),
    onError: async () => {
      setError('The hold could not be changed: someone may have changed it already.');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
  });

  const toggle = () => {
    setError('');
    if (!person) return;
    once(() => hold.mutateAsync(!person.held));
  };

  return (
    <>
      <td data-testid="person-hold">{person?.held ? 'yes' : 'no'}</td>
      <td>
        <button type="button" data-testid="person-hold-toggle" onClick={toggle} disabled={hold.isPending}>
          {person?.held ? 'Release' : 'Hold'}
        </button>
        {error && <span data-testid="person-error">{error}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 35, Component: HoldColumns }),
  PersonCells.fill({ order: 35, Component: PersonHold }),
];

