/** Closes the period, refusing one already closed, and fixes its due-total: the due of the claims that
 *  count dated in it (not the OPEN or PENDING claims of a person on hold), as shown now (a settled claim's fixed due; an open one's at the rate in force on its date for the grade in force on its
 *  date, rounded half up when dated before the sheet's policy date (its today when none is set), half to even otherwise, and raised to the sheet's floor unless it is a correction), none where no rate applies. */
public class ClosePeriod {
    public void close(@Val Period period, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets)
            throws InvalidPeriodException {
        if (period.isClosed()) {
            throw new InvalidPeriodException("The period " + period.getName() + " is already closed.");
        }
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(period.getSheetId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal floor = settings.floor(period.getSheetId());
        LocalDate today = sheets.findById(period.getSheetId()).map((s) -> s.getToday()).orElse(null);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.findBySheetIdOrderByIdDesc(period.getSheetId())) {
            if (!c.getStatus().counts() || !period.contains(c.getDate())
                    || (c.getStatus().live() && byId.get(c.getPersonId()).isHeld())) {
                continue;
            }
            BigDecimal due = c.getStatus() == ClaimStatus.SETTLED ? c.getSettledDue()
                    : rates.findInForce(c.getSheetId(), byId.get(c.getPersonId()).gradeOn(c.getDate()), c.getDate())
                            .map((r) -> c.getAmount().multiply(r.getRate())
                                    .divide(BigDecimal.valueOf(100), 2, settings.rounding(c.getSheetId(), c.getDate(), today)))
                            .map((d) -> c.isCorrection() ? d : d.max(floor))
                            .orElse(null);
            if (due != null) {
                total = total.add(due);
            }
        }
        period.close(total);
    }
}
package net.officefloor.hq.app.claim;

/** A claim's status. It starts DRAFT; DRAFT → OPEN → SETTLED; DRAFT or OPEN → VOID. A clerk settling a claim
 *  whose due is above the clerk limit moves it OPEN → PENDING instead; a steward approves it (PENDING → SETTLED)
 *  or rejects it (PENDING → OPEN). SETTLED and VOID are final. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to {@code to} by opening, settling or voiding it (approving
     *  and rejecting a PENDING claim are checked by {@link #awaitsApproval()}). */
    public boolean canBecome(ClaimStatus to) {
        return switch (to) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status waits for a steward to approve or reject it. */
    public boolean awaitsApproval() {
        return this == PENDING;
    }

    /** Whether a claim in this status is live: OPEN, or PENDING (which counts as open everywhere). */
    public boolean live() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status counts toward claimed, due-total and every total. */
    public boolean counts() {
        return live() || this == SETTLED;
    }
}
